int nb_decor = 0;


void init_decor()
{
	gen_decor(1,30,PALM_TREE);
	gen_decor(215,50,PALM_TREE);
}


void gen_decor(int x, int y, int type) {

char i;


for (i = 0; i < MAX_DECOR; i++) {
    if (!(decor[i].flags & DECOR_ACTIVE)) {
        decor[i].box.x = x;
        decor[i].box.y = y << 4;
        decor[i].type = type;
        decor[i].box.w = decor_types[decor[i].type].sprite[0];
        decor[i].box.h = decor_types[decor[i].type].sprite[1];
        decor[i].flags |= DECOR_ACTIVE;
        decor[i].flags |= DECOR_SOLID;
        
        nb_decor++;
        break; // on a trouvé un slot, on sort de la boucle
    }
    
    
}
	
}



void update_decor(){

	int i;
	
	
	
	for (i=MAX_DECOR;i>0;i--){
		if (decor[i].flags & DECOR_ACTIVE) {
			decor[i].box.y+=scroll_speed;
			put_sprite (decor[i].box.x,decor[i].box.y, decor_types[decor[i].type].sprite);
			if (decor[i].box.y > (200 << 4))
				{
    			decor[i].flags &= ~DECOR_ACTIVE;
    			nb_decor--;
    			}
    		}
	}
}
